from django.utils import timezone


def populate_exam_session_windows(apps, schema_editor):
    ExamSession = apps.get_model("exams", "ExamSession")
    for session in ExamSession.objects.all().iterator():
        if not session.date or not session.start_time:
            continue
        opens_at = timezone.make_aware(datetime.combine(session.date, session.start_time))
        if session.end_time:
            closes_at = timezone.make_aware(datetime.combine(session.date, session.end_time))
        else:
            closes_at = opens_at + timedelta(hours=1)
        if closes_at <= opens_at:
            closes_at = opens_at + timedelta(hours=1)
        ExamSession.objects.filter(pk=session.pk).update(
            opens_at=opens_at,
            closes_at=closes_at,
        )


